<script setup lang="ts">
import { onMounted, ref } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import DataGrid, { type GridColumn } from "@/components/DataGrid.vue";
import { ApiError } from "@/services/http";
import { createAcademicPeriod, listAcademicPeriods, setAcademicPeriodState, updateAcademicPeriod, type AcademicPeriod } from "@/services/administracion";

const items = ref<AcademicPeriod[]>([]); const search = ref(""); const state = ref<"all" | "active" | "inactive">("all"); const page = ref(1); const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const loading = ref(false); const saving = ref(false); const listError = ref(""); const mutationError = ref(""); const warning = ref(""); const success = ref(""); const modal = ref(false); const editing = ref<AcademicPeriod | null>(null);
const form = ref({ codigoPeriodoAcademico: "", nombrePeriodoAcademico: "", fechaInicioPeriodoAcademico: "", fechaFinPeriodoAcademico: "", estadoPeriodoAcademico: true });
const columns: GridColumn[] = [{ key: "codigoPeriodoAcademico", label: "Código", width: "17%" }, { key: "nombrePeriodoAcademico", label: "Descripción", width: "25%" }, { key: "fechaInicioPeriodoAcademico", label: "Inicio", width: "13%" }, { key: "fechaFinPeriodoAcademico", label: "Finalización", width: "13%" }, { key: "vigenciaPeriodoAcademico", label: "Vigencia", width: "15%" }, { key: "estadoPeriodoAcademico", label: "Estado", width: "10%" }];
const rows = () => items.value as unknown as Record<string, unknown>[];
const rowKey = (row: Record<string, unknown>) => String(row.idPeriodoAcademico);
const message = (cause: unknown) => cause instanceof ApiError ? cause.message : "Ocurrió un error inesperado";
async function load(): Promise<boolean> { loading.value = true; listError.value = ""; try { const result = await listAcademicPeriods({ page: page.value, pageSize: 10, search: search.value, estado: state.value, sortBy: "fechaInicioPeriodoAcademico", sortDirection: "desc" }); items.value = result.items; pagination.value = result.pagination; return true; } catch (cause) { listError.value = message(cause); return false; } finally { loading.value = false; } }
function resetForm() { editing.value = null; form.value = { codigoPeriodoAcademico: "", nombrePeriodoAcademico: "", fechaInicioPeriodoAcademico: "", fechaFinPeriodoAcademico: "", estadoPeriodoAcademico: true }; }
function edit(item: AcademicPeriod | null) { mutationError.value = ""; editing.value = item; form.value = { codigoPeriodoAcademico: item?.codigoPeriodoAcademico ?? "", nombrePeriodoAcademico: item?.nombrePeriodoAcademico ?? "", fechaInicioPeriodoAcademico: item?.fechaInicioPeriodoAcademico?.slice(0, 10) ?? "", fechaFinPeriodoAcademico: item?.fechaFinPeriodoAcademico?.slice(0, 10) ?? "", estadoPeriodoAcademico: item?.estadoPeriodoAcademico ?? true }; modal.value = true; }
async function save() { if (saving.value) return; saving.value = true; mutationError.value = ""; warning.value = ""; success.value = ""; try { if (editing.value) await updateAcademicPeriod(editing.value.idPeriodoAcademico, form.value); else await createAcademicPeriod(form.value); modal.value = false; resetForm(); success.value = "Período académico guardado correctamente."; if (!await load()) warning.value = "El período se guardó correctamente, pero no fue posible actualizar el listado. Puede reintentarlo."; } catch (cause) { mutationError.value = message(cause); } finally { saving.value = false; } }
async function toggle(item: AcademicPeriod) { if (saving.value || !window.confirm(`¿Confirma ${item.estadoPeriodoAcademico ? "desactivar" : "activar"} el período ${item.codigoPeriodoAcademico}?`)) return; mutationError.value = ""; warning.value = ""; success.value = ""; saving.value = true; try { await setAcademicPeriodState(item.idPeriodoAcademico, !item.estadoPeriodoAcademico); success.value = "Estado del período actualizado correctamente."; if (!await load()) warning.value = "El estado se actualizó correctamente, pero no fue posible actualizar el listado. Puede reintentarlo."; } catch (cause) { mutationError.value = message(cause); } finally { saving.value = false; } }
function changePage(next: number) { page.value = next; void load(); }
onMounted(() => void load());
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración', to: '/administracion/configuracion' }, { label: 'Configuración', to: '/administracion/configuracion' }, { label: 'Períodos académicos' }]" />
  <PageHeader eyebrow="Configuración" title="Períodos académicos" description="Administre los períodos académicos institucionales utilizados por Solicitudes." action-label="Nuevo período" @action="edit(null)" />
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="warning" class="bo-notice bo-state-warning">{{ warning }} <button class="bo-link" @click="load">Reintentar</button></div><div v-if="mutationError && !modal" class="bo-notice bo-state-error">{{ mutationError }}</div><div v-if="listError && items.length && !warning" class="bo-notice bo-state-warning">No fue posible cargar la actualización del listado. <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="page = 1; load()"><input v-model="search" placeholder="Buscar por código o descripción..." aria-label="Buscar períodos académicos" /><select v-model="state"><option value="all">Todos los estados</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select><button class="bo-btn bo-btn-primary">Buscar</button></form><DataGrid :columns="columns" :rows="rows()" :row-key="rowKey" :pagination="pagination" :loading="loading" :error="items.length ? '' : listError" empty-text="No hay períodos académicos registrados." @page="changePage"><template #cell-fechaInicioPeriodoAcademico="{ row }">{{ String(row.fechaInicioPeriodoAcademico).slice(0, 10) }}</template><template #cell-fechaFinPeriodoAcademico="{ row }">{{ String(row.fechaFinPeriodoAcademico).slice(0, 10) }}</template><template #cell-vigenciaPeriodoAcademico="{ row }"><span class="status-badge">{{ row.vigenciaPeriodoAcademico }}</span></template><template #cell-estadoPeriodoAcademico="{ row }"><span class="status-badge" :class="{ 'status-badge--inactive': !row.estadoPeriodoAcademico }">{{ row.estadoPeriodoAcademico ? 'Activo' : 'Inactivo' }}</span></template><template #actions="{ row }"><button class="bo-action" :disabled="saving" @click="edit(row as unknown as AcademicPeriod)">Editar</button><button class="bo-action" :class="{ danger: row.estadoPeriodoAcademico }" :disabled="saving" @click="toggle(row as unknown as AcademicPeriod)">{{ row.estadoPeriodoAcademico ? 'Desactivar' : 'Activar' }}</button></template></DataGrid></section>
  <div v-if="modal" class="bo-modal-backdrop" @click.self="!saving && (modal = false)"><section class="bo-modal period-modal"><header><div><span class="bo-eyebrow">Configuración</span><h2>{{ editing ? 'Editar período académico' : 'Nuevo período académico' }}</h2></div><button class="bo-close" type="button" :disabled="saving" @click="modal = false">×</button></header><div v-if="mutationError" class="bo-state bo-state-error" role="alert">{{ mutationError }}</div><form class="bo-form" @submit.prevent="save"><label>Código *<input v-model="form.codigoPeriodoAcademico" maxlength="30" required :disabled="Boolean(editing) || saving" /></label><label>Descripción *<input v-model="form.nombrePeriodoAcademico" maxlength="150" required :disabled="saving" /></label><label>Fecha de inicio *<input v-model="form.fechaInicioPeriodoAcademico" type="date" required :disabled="saving" /></label><label>Fecha de finalización *<input v-model="form.fechaFinPeriodoAcademico" type="date" required :disabled="saving" /></label><label class="bo-check-label"><input v-model="form.estadoPeriodoAcademico" type="checkbox" :disabled="saving" /> Habilitado administrativamente</label><footer class="form-actions"><button type="button" class="bo-btn" :disabled="saving" @click="modal = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving">{{ saving ? 'Guardando…' : 'Guardar' }}</button></footer></form></section></div>
</template>

<style scoped>.period-modal{width:min(560px,calc(100vw - 32px))}.period-modal input{width:100%;box-sizing:border-box}.form-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.bo-check-label{display:flex;align-items:center;gap:8px}.bo-check-label input{width:auto}</style>
